parameters.jsCode:
// Parse incoming change request
const request = $input.first().json;

const changeRequest = {
  id: `CHG-${Date.now()}`,
  submittedAt: new Date().toISOString(),
  submittedBy: request.submitter || request.email || 'unknown',

  // Change details
  title: request.title || 'Network Change',
  description: request.description || '',
  changeType: request.changeType || 'standard', // standard, normal, emergency

  // Affected systems
  affectedDevices: request.devices || [],
  affectedSites: request.sites || [],
  affectedServices: request.services || [],

  // Implementation details
  plannedStart: request.plannedStart || '',
  plannedEnd: request.plannedEnd || '',
  rollbackPlan: request.rollbackPlan || '',
  testPlan: request.testPlan || '',

  // Risk factors
  impactLevel: request.impact || 'low', // low, medium, high, critical
  urgency: request.urgency || 'low',
  outageRequired: request.outageRequired || false,
  outageMinutes: request.outageMinutes || 0,

  // Attachments
  configChanges: request.configChanges || '',
  documentationLinks: request.links || []
};

return {
  json: changeRequest
};

