// Emergency change process - expedited approval
const data = $input.first().json;

return {
  json: {
    ...data,
    isEmergency: true,
    emergencyJustification: data.description,
    emergencyApprovalRequired: true,
    escalationLevel: 'immediate'
  }
};

// Schedule the change implementation
const data = $input.first().json;

const implementation = {
  changeId: data.id,
  scheduledStart: data.plannedStart || new Date(Date.now() + 86400000).toISOString(),
  scheduledEnd: data.plannedEnd || new Date(Date.now() + 90000000).toISOString(),
  implementer: data.assignee || data.submittedBy,
  status: 'scheduled',
  preChecks: [
    'Verify backup exists',
    'Confirm maintenance window',
    'Notify affected users',
    'Prepare rollback commands'
  ],
  postChecks: [
    'Verify connectivity',
    'Run smoke tests',
    'Check monitoring alerts',
    'Update documentation'
  ]
};

return {
  json: {
    ...data,
    implementation
  }
};

// Define compliance rules
const rules = [
  {
    id: 'SEC-001',
    name: 'SSH Version 2 Required',
    severity: 'high',
    pattern: 'ip ssh version 2',
    mustExist: true,
    platforms: ['cisco_ios', 'cisco_nxos']
  },
  {
    id: 'SEC-002',
    name: 'Telnet Disabled',
    severity: 'critical',
    pattern: 'transport input telnet',
    mustExist: false,
    platforms: ['cisco_ios', 'cisco_nxos']
  },
  {
    id: 'SEC-003',
    name: 'Password Encryption',
    severity: 'high',
    pattern: 'service password-encryption',
    mustExist: true,
    platforms: ['cisco_ios']
  },
  {
    id: 'SEC-004',
    name: 'NTP Configured',
    severity: 'medium',
    pattern: 'ntp server',
    mustExist: true,
    platforms: ['all']
  },
  {
    id: 'SEC-005',
    name: 'Logging Enabled',
    severity: 'high',
    pattern: 'logging host',
    mustExist: true,
    platforms: ['all']
  },
  {
    id: 'SEC-006',
    name: 'SNMP Community Not Default',
    severity: 'critical',
    pattern: 'snmp-server community public',
    mustExist: false,
    platforms: ['all']
  },
  {
    id: 'NET-001',
    name: 'CDP Disabled on Edge',
    severity: 'medium',
    pattern: 'no cdp enable',
    mustExist: true,
    platforms: ['cisco_ios'],
    interfaceType: 'edge'
  },
  {
    id: 'NET-002',
    name: 'Spanning Tree BPDU Guard',
    severity: 'high',
    pattern: 'spanning-tree bpduguard enable',
    mustExist: true,
    platforms: ['cisco_ios', 'cisco_nxos'],
    interfaceType: 'access'
  }
];

return {
  json: {
    rules,
    checkTime: new Date().toISOString()
  }
};

// Run compliance checks against all device configurations
const data = $input.first().json;
const rules = data.rules || [];
const configs = data.configs || [];

const violations = [];
const compliant = [];

configs.forEach(device => {
  const config = device.config || '';
  const platform = device.platform || '';

  rules.forEach(rule => {
    // Check if rule applies to this platform
    if (rule.platforms.includes('all') || rule.platforms.includes(platform)) {
      const hasPattern = config.includes(rule.pattern);
      const isViolation = rule.mustExist ? !hasPattern : hasPattern;

      if (isViolation) {
        violations.push({
          deviceHostname: device.hostname,
          deviceIp: device.ip,
          platform: platform,
          ruleId: rule.id,
          ruleName: rule.name,
          severity: rule.severity,
          pattern: rule.pattern,
          expected: rule.mustExist ? 'present' : 'absent',
          actual: hasPattern ? 'present' : 'absent'
        });
      } else {
        compliant.push({
          deviceHostname: device.hostname,
          ruleId: rule.id
        });
      }
    }
  });
});

const summary = {
  totalDevices: configs.length,
  totalRules: rules.length,
  totalViolations: violations.length,
  criticalViolations: violations.filter(v => v.severity === 'critical').length,
  highViolations: violations.filter(v => v.severity === 'high').length,
  mediumViolations: violations.filter(v => v.severity === 'medium').length
};

return {
  json: {
    summary,
    violations,
    compliant,
    checkTime: data.checkTime
  }
};

