parameters.jsCode:
// Generate compliance report
const data = $input.first().json;

const report = {
  reportId: `COMP-${Date.now()}`,
  generatedAt: new Date().toISOString(),
  summary: data.summary,
  aiInsights: data.message?.content || '',
  violations: data.violations,
  complianceScore: data.summary.totalDevices > 0 
    ? ((1 - (data.summary.totalViolations / (data.summary.totalDevices * 10))) * 100).toFixed(1)
    : 100,
  trend: 'stable', // Would compare with previous reports
  nextScheduledCheck: new Date(Date.now() + 86400000).toISOString()
};

return {
  json: report
};

